import React, { useState, useEffect, useMemo, useRef } from 'react'
import AdaptableCard from 'components/shared/AdaptableCard'
import DataTable from 'components/shared/DataTable'
import Tabs from 'components/ui/Tabs'
import debounce from 'lodash/debounce'
import Button from 'components/ui/Buttons'
import Input from 'components/ui/Input'
import toast from 'components/ui/toast'
import Notification from 'components/ui/Notification'
import { Link, useNavigate } from 'react-router-dom'
import { MdCreate, MdAdd, MdDelete, MdImportExport } from "react-icons/md"
import { HiSearch } from 'react-icons/hi'
import { BiMailSend } from "react-icons/bi";
import { apiPurchaseOrderGet } from 'services/PurchaseOrderService'
import { exportToExcel } from "react-easy-export";
import NumberFormat from 'react-number-format';
import Tooltip from 'components/ui/Tooltip'
import ViewPurchaseOrder from './ViewPurchaseOrder'

const { TabNav, TabList, TabContent } = Tabs

const PurchaseOrder = () => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(true)
    const [selectedRows, setSelectedRows] = useState([])
    const [tableData, setTableData] = useState({
        total: 0,
        pageIndex: 1,
        pageSize: 10,
        query: '',
        sort: {
            order: '',
            key: '',
        },
        status: 'pending'
    });

    const [statusCount, setStatusCount] = useState({ advance: 0, approved: 0, inActive: 0, open: 0, payment_pending: 0, pending: 0, rejected: 0 })

    const tabChanges = (tab) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ status: tab },
        }))
    }

    const navigate = useNavigate();
    const inputRef = useRef(null)

    const debounceFn = debounce(handleDebounceFn, 1000)

    function handleDebounceFn(val) {
        if (typeof val === 'string' && (val.length > 1 || val.length === 0)) {
            setTableData((prevData) => ({
                ...prevData,
                ...{ query: val, pageIndex: 1 },
            }))
        }
    }

    const handleChange = (e) => {
        debounceFn(e.target.value)
    }

    const handleRowClick = (dataid) => {
        // navigate(`/transaction/purchase-order/edit-purchase-order/${dataid}`);
        console.log(dataid);
    }

    const columns = useMemo(() => (
        [
            {
                header: 'Order Date',
                cell: (props) => {
                    let a = new Date(props.row.original.order_date)
                    return props.row.original.order_date === null ? '' : `${a.getDate() < 10 ? '0' + a.getDate() : a.getDate()}-${a.getMonth() + 1 < 10 ? '0' + (a.getMonth() + 1) : a.getMonth() + 1}-${a.getFullYear()}`
                },
                accessorKey: 'order_date',
            },
            {
                header: 'Po. No.',
                accessorKey: 'po_no'
            },
            {
                header: 'Vendor Name',
                cell: (props) => {
                    return props.row.original.vendor === null ? '' : props.row.original.vendor['vendor_name']
                }
            },
            {
                header: 'Depot Name',
                cell: (props) => {
                    return props.row.original.depot === null ? '' : props.row.original.depot['depot_name']
                }
            },
            {
                header: 'Amount',
                cell: (props) => {
                    return <NumberFormat displayType='text' prefix={"₹"} thousandsGroupStyle={"lakh"} decimalScale={2} value={props.row.original.po_amount} allowLeadingZeros thousandSeparator="," />
                }
            },
            {
                header: 'Action',
                width: 150,
                cell: (props) => (
                    <>
                        <Tooltip title="Edit Purchase Order">
                            <Button
                                shape="circle"
                                size="sm"
                                variant="twoTone"
                                icon={<MdCreate />}
                                className="text-sm mr-3"
                                onClick={() => { navigate(`/transaction/purchase-order/edit-purchase-order/${props.row.original.id}`) }}
                            />
                        </Tooltip>
                        {/* <Tooltip title="View Purchase Order">
                            <Link target='_blank' to={`/transaction/purchase-order/view-purchase-order/${props.row.original.id}`}>
                                <Button
                                    shape="circle"
                                    size="sm"
                                    variant="twoTone"
                                    color="red-600"
                                    icon={<FaFilePdf />}
                                    className="text-sm mr-3"
                                />
                            </Link>
                        </Tooltip> */}
                        <ViewPurchaseOrder />
                        <Tooltip title="Send Mail">
                            <Button
                                shape="circle"
                                size="sm"
                                variant="twoTone"
                                color="blue-600"
                                icon={<BiMailSend />}
                                onClick={() => { handleRowClick(props.row.original.id) }}
                            />
                        </Tooltip>
                    </>
                ),
            },
        ]
    ), [])

    const handlePaginationChange = (pageIndex) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageIndex } }))
    }

    const handleSelectChange = (pageSize) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageSize } }))
    }

    const handleSort = ({ order, key }) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ sort: { order, key } },
        }))
    }

    const handleRowSelect = (checked, row) => {
        console.log('row', row)
        if (checked) {
            setSelectedRows((prevData) => {
                if (!prevData.includes(row)) {
                    return [...prevData, ...[row]]
                }
                return prevData
            })
        } else {
            setSelectedRows((prevData) => {
                if (prevData.includes(row)) {
                    return prevData.filter((prevRow) => prevRow.id !== row.id)
                }
                return prevData
            })
        }
    }

    const handleAllRowSelect = (checked, rows) => {
        console.log('rows', rows)
        if (checked) {
            const originalRows = rows.map((row) => row.original)
            const selectedIds = []
            originalRows.forEach((row) => {
                selectedIds.push(row)
            })
            setSelectedRows(selectedIds)
        } else {
            setSelectedRows([])
        }
    }

    console.log("PurchaseOrder.js Loading....")

    useEffect(() => {
        const fetchData = async () => {
            // setLoading(true)
            await apiPurchaseOrderGet(tableData).then(data => {
                console.log(data.data)
                if (data.data) {
                    setStatusCount({
                        advance: data.data['statusCount'].advance,
                        approved: data.data['statusCount'].approved,
                        inActive: data.data['statusCount'].inActive,
                        open: data.data['statusCount'].open,
                        payment_pending: data.data['statusCount'].payment_pending,
                        pending: data.data['statusCount'].pending,
                        rejected: data.data['statusCount'].rejected,

                    })
                    setData(data.data['rows'])
                    setTableData((prevData) => ({
                        ...prevData,
                        ...{ total: data.data['total'] },
                    }))
                    setLoading(false)
                }
            }).catch(error => {
                if (error.response.status === 500) {
                    console.log(error)
                    setLoading(false)
                }
            })
            return true
        }
        fetchData()
        // eslint-disable-next-line react-hooks/exhaustive-deps

    }, [tableData.pageIndex, tableData.sort, tableData.pageSize, tableData.query, tableData.status])
    return (
        <AdaptableCard className="card-shadow">
            <div className='lg:flex items-center justify-between mb-0'>
                <h3 className="mb-4 lg:mb-0 ">Purchase Order</h3>
                <div className='flex flex-row lg:flex-row lg:items-center'>
                    <Input
                        ref={inputRef}
                        placeholder="Search..."
                        size="sm"
                        className="lg:w-52 mr-4"
                        onChange={handleChange}
                        prefix={<HiSearch className="text-lg" />}
                    />
                    <Link to={'/transaction/purchase-order/add-purchase-order'} className=' mr-4 inline-flex'>
                        <Button size="sm" variant="solid" icon={<MdAdd />}>
                            <span>Add Purchase Order</span>
                        </Button>
                    </Link>
                    <div className=' inline-flex'>
                        <Button size="sm" variant="solid" color="emerald-600" icon={<MdImportExport />} onClick={() => { exportToExcel(selectedRows) }} disabled={!selectedRows.length > 0}>
                            <span>Download</span>
                        </Button>
                    </div>

                </div>
            </div>

            <Tabs defaultValue="pending" onChange={(tabValue) => { tabChanges(tabValue) }}>
                <TabList className="justify-end">
                    <TabNav value="pending">Pending Approved {`(${statusCount.pending})`}</TabNav>
                    <TabNav value="open">Open {`(${statusCount.open})`}</TabNav>
                    <TabNav value="payment_pending">Payment Pending {`(${statusCount.payment_pending})`}</TabNav>
                    <TabNav value="advance">Advance {`(${statusCount.advance})`}</TabNav>
                    <TabNav value="rejected">Rejected {`(${statusCount.rejected})`}</TabNav>
                    <TabNav value="approved">Approved {`(${statusCount.approved})`}</TabNav>
                </TabList>
                <div className="p-1">
                    <TabContent value="pending">
                    </TabContent>
                    <TabContent value="open">
                    </TabContent>
                    <TabContent value="payment_pending">
                    </TabContent>
                    <TabContent value="advance">
                    </TabContent>
                    <TabContent value="rejected">
                    </TabContent>
                    <TabContent value="approved">
                    </TabContent>
                </div>
            </Tabs>
            <DataTable
                selectable
                columns={columns}
                data={data}
                loading={loading}
                pagingData={tableData}
                onPaginationChange={handlePaginationChange}
                onSelectChange={handleSelectChange}
                onSort={handleSort}
                onCheckBoxChange={handleRowSelect}
                onIndeterminateCheckBoxChange={handleAllRowSelect}
                columnShow={+false}
            />
        </AdaptableCard>
    )
}

export default PurchaseOrder
